def _facet_run_nested_resource_demand_v1(caps):
 import tools.run_validation_gates as _f
 from tools import validation_reliability as owner
 need = owner._preflight_require_v1
 geometry = caps.get('phase_source')
 if geometry is None or not geometry['nested_positions']: return None
 p, w = geometry['count'], len(geometry['nested_positions'])
 evidence, output = caps['evidence_programme'], caps['output_partition']
 h, receipt = evidence['binding_payload_bytes'], evidence['atomic_payload_bytes']
 stream = output['application_stream_bytes']
 need(0 < w <= p and h == receipt == 1048576 and type(stream) is int and stream > 0,
  'ORDINARY_NESTED_ORIGINAL_SOURCE_AND_OUTPUT_GEOMETRY')
 initial = 3 + 5 * evidence['query_command_count'] + 2 * evidence['native_response_count'] + 16
 direct, rounds, projections = initial + 3*p + w + 4, p + 6, w*(w-1)//2
 f = max(stream, h, receipt)
 need(f <= 128 << 20, 'ORDINARY_NESTED_SOURCE_FILE_LIMIT_WITHIN_NATIVE_FSIZE')
 one = 2*stream + receipt
 read = w*((5 + 3*rounds)*one + (3 + rounds)*h + 32)
 write = w*(one + h)
 retained = w*(4*one + 3*h + 2*f)
 collector = retained + 3*f + 3*65536 + 2
 inventories = w*(4*rounds + 12) + 1
 inventory_calls = inventories*(2*direct + 10)
 file_reads = w*(10*rounds + 20)
 fixed_calls = 16*file_reads + 60*4*w + 40*(projections + w) + (3*8*64 + 256)*w
 metadata_calls = read + write + inventory_calls + fixed_calls
 native_calls = 6*(projections + w) + 8*w
 native_read = 24*(projections + w) + 28*w + 2*w*1536
 native_write = 8*(projections + w) + 2*w*48
 name_read = inventories*direct*caps['limits']['single_path_byte_limit']
 bytes_needed = (output['application_bytes'] + w*(h + receipt)
  + (2*(128 << 20) + h + receipt) + 4096*(2*w + projections))
 inodes = 5*w + projections + 4
 return (p, w, initial, direct, rounds, projections, read, write, retained,
  collector, metadata_calls, native_calls, native_read, native_write,
  name_read, bytes_needed, inodes, 3*w + 4)


def _facet_fn_control_lexical_forward_activation_v1(scope, activation):
 import tools.validation_reliability as _facet
 import types
 from tools import validation_scope_registry as reg
 if (type(activation) is not tuple or len(activation)!=7 or activation[0] is not scope
   or activation[2] is not _facet._ordinary_source_data_lexical_admission_v1
   or type(activation[4]) is not tuple or len(activation[4])!=3
   or type(activation[6]) is not tuple or len(activation[6])!=3):
  raise ValueError('CONTROL_ORIGINAL_LEXICAL_FORWARD_ACTIVATION')
 product=activation[1]
 programme=product['programme']
 scanner=reg._facet_fn_source_data_lexical_admission_v1
 forwarded=(reg._facet_fn_source_data_utf8_scalar_v1,reg._facet_fn_source_data_json_span_v1)
 rows=_facet._ordinary_control_source_product_check_v1(scope,product)
 matched=tuple(row for row in rows if row[1] is scanner)
 if len(matched)!=1 or matched[0][2] is not scanner.__code__:
  raise ValueError('CONTROL_ORIGINAL_LEXICAL_FORWARD_SCANNER')
 children=dict((row[0],row) for row in activation[6])
 for index,name in enumerate(('checkpoint','visit','bump')):
  row=children[name];function=activation[4][index]
  if (row[1] is not function or type(function) is not types.FunctionType
    or row[2] is not function.__code__
    or row[4] is not function.__closure__
    or len(row[4])!=len(row[5])
    or any(cell.cell_contents is not value for cell,value in zip(row[4],row[5]))):
   raise ValueError('CONTROL_ORIGINAL_LEXICAL_FORWARD_LIVE_CHILD')
 for caller in forwarded:
  selected=tuple(row for row in programme['selectors'] if row[4] is caller)
  if len(selected)!=1:raise ValueError('CONTROL_ORIGINAL_LEXICAL_FORWARD_SELECTOR')
  formal_sites=tuple(row for row in programme['site_rows']
   if row[0]==selected[0][0] and row[1][0]=='CALL'
   and any(row[1][5].startswith("Call(func=Name(id="+repr(name)+", ctx=Load())")
    for name in (('visit',) if caller is forwarded[0] else ('visit','bump'))))
  if not formal_sites:raise ValueError('CONTROL_ORIGINAL_LEXICAL_FORWARD_LIVE_SITE_COVERAGE')
  for row in formal_sites:
   routes=tuple(route for route in row[2] if route[0] is scanner and route[3]=='LEXICAL_CALL')
   if len(routes)!=1:raise ValueError('CONTROL_ORIGINAL_LEXICAL_FORWARD_ONE_LIVE_ROUTE')
   route=routes[0];child=children[route[2].co_name]
   if (route[1]!=(child[3],) or route[2] is not child[2]
     or route[4] is not caller):
    raise ValueError('CONTROL_ORIGINAL_LEXICAL_FORWARD_LIVE_ROUTE')
   _facet._ordinary_control_lexical_forward_route_v1(scope,*route[:3],caller,row[1],programme['selectors'])
 return activation


