def _facet_fn_control_bytecode_values_v1(code):
 import tools.validation_scope_registry as _facet
 import tools.validation_reliability as _facet
 import dis, types
 if type(code) is not types.CodeType:
  raise ValueError('CONTROL_ORIGINAL_TYPED_BYTECODE_OPERAND')
 def projected():
  for offset,start,operation,argument in dis._unpack_opargs(code.co_code):
   name=dis._all_opname[operation]
   value=None
   if name=='LOAD_CONST':value=code.co_consts[argument]
   elif name=='LOAD_GLOBAL':value=code.co_names[argument>>1]
   elif name in ('STORE_GLOBAL','DELETE_GLOBAL','STORE_NAME','DELETE_NAME'):
    value=code.co_names[argument]
   elif name in ('STORE_FAST','DELETE_FAST','STORE_DEREF','DELETE_DEREF'):
    value=code._varname_from_oparg(argument)
   yield offset,name,argument,value
 return projected()


def _facet_fn_control_source_site_codes_v1(function, definition):
 import tools.validation_reliability as _facet
 import ast, types
 if type(function) is not types.FunctionType or type(definition) is not ast.FunctionDef:
  raise ValueError('CONTROL_ORIGINAL_SOURCE_SITE_CODE_OPERANDS')
 rows=[]
 def child(parent,path,node,name,line):
  choices=tuple((index,code) for index,code in enumerate(parent.co_consts)
   if type(code) is types.CodeType and code.co_name==name and code.co_firstlineno==line)
  if len(choices)>1:
   choices=tuple((index,code) for index,code in choices if any(
    start is not None and column is not None and node.lineno<=start<=node.end_lineno
    and (start!=node.lineno or column>=node.col_offset)
    and (start!=node.end_lineno or column<node.end_col_offset)
    for start,end,column,end_column in code.co_positions()))
  if len(choices)!=1:raise ValueError('CONTROL_ONE_ORIGINAL_SOURCE_SITE_CHILD_CODE')
  index,code=choices[0]
  return code,path+(index,)
 def visit(node,code,path):
  if isinstance(node,(ast.Call,ast.Attribute,ast.Import,ast.ImportFrom)):
   kind=('CALL' if isinstance(node,ast.Call) else 'ATTRIBUTE'
    if isinstance(node,ast.Attribute) else 'IMPORT')
   site=(kind,node.lineno,node.col_offset,node.end_lineno,node.end_col_offset,
    ast.dump(node,include_attributes=False))
   rows.append((site,function,path,code))
  if isinstance(node,ast.FunctionDef):
   if node is definition:
    for statement in node.body:visit(statement,code,path)
    for value in node.args.defaults:visit(value,code,path)
    for value in node.args.kw_defaults:
     if value is not None:visit(value,code,path)
    return
   for decorator in node.decorator_list:visit(decorator,code,path)
   for value in node.args.defaults:visit(value,code,path)
   for value in node.args.kw_defaults:
    if value is not None:visit(value,code,path)
   line=min((node.lineno,)+tuple(item.lineno for item in node.decorator_list))
   current,current_path=child(code,path,node,node.name,line)
   for statement in node.body:visit(statement,current,current_path)
   return
  if isinstance(node,ast.Lambda):
   for value in node.args.defaults:visit(value,code,path)
   for value in node.args.kw_defaults:
    if value is not None:visit(value,code,path)
   current,current_path=child(code,path,node,'<lambda>',node.lineno)
   visit(node.body,current,current_path)
   return
  if isinstance(node,ast.GeneratorExp):
   current,current_path=child(code,path,node,'<genexpr>',node.lineno)
   visit(node.elt,current,current_path)
   for index,generator in enumerate(node.generators):
    visit(generator.target,current,current_path)
    visit(generator.iter,code if index==0 else current,path if index==0 else current_path)
    for condition in generator.ifs:visit(condition,current,current_path)
   return
  if isinstance(node,(ast.AsyncFunctionDef,ast.ClassDef,ast.Await)):
   raise ValueError('CONTROL_UNSELECTED_SITE_CODE_SCOPE')
  for value in ast.iter_child_nodes(node):visit(value,code,path)
 visit(definition,function.__code__,())
 expected=_facet._ordinary_control_source_sites_v1(definition)
 indexed={row[0]:row for row in rows}
 if len(indexed)!=len(rows) or set(indexed)!=set(expected):
  raise ValueError('CONTROL_EXACT_SOURCE_SITE_CODE_COVERAGE')
 return tuple(indexed[site] for site in expected)


